#!/usr/bin/env python3
"""Actual isolated same-model assessments of two genuine native histories per integration route."""
import argparse,json,subprocess,os,hashlib,datetime,concurrent.futures,uuid
from pathlib import Path
parser=argparse.ArgumentParser();parser.add_argument('--directory',default='evals/results/guided-selection-0.1.3');args=parser.parse_args();root=Path.cwd();source=root/args.directory;out=root/'.superpowers/model-run'/('guided-judges-'+datetime.datetime.now(datetime.timezone.utc).strftime('%Y%m%dT%H%M%SZ')+'-'+uuid.uuid4().hex[:8]);out.mkdir(parents=True)
policy=(root/'evals/fixtures/guided-selection-judge-policy.txt').read_text();env=dict(os.environ);env.pop('OPENAI_API_KEY',None)
schema={'type':'object','properties':{'verdict':{'type':'string','enum':['pass','fail','uncertain']},'findings':{'type':'array','items':{'type':'object','properties':{'turn':{'type':'integer'},'expected':{'type':'string'},'observed':{'type':'string'}},'required':['turn','expected','observed'],'additionalProperties':False}},'presentationObservations':{'type':'array','items':{'type':'string'}},'scope':{'type':'string'}},'required':['verdict','findings','presentationObservations','scope'],'additionalProperties':False}
def turns(run):return [{'request':t['request'],'reply':t['reply'],'visibleMessages':[e['item']['text']for e in t['events']if e.get('type')=='item.completed'and e.get('item',{}).get('type')=='agent_message'],'retrievalCalls':[{k:v for k,v in e['item'].items()if k!='result'}for e in t['events']if e.get('type')=='item.completed'and e.get('item',{}).get('type')in['web_search','mcp_tool_call']]}for t in run['turns']]
def judge(route):
 directory=out/route;directory.mkdir();schema_path=directory/'schema.json';schema_path.write_text(json.dumps(schema));reply=directory/'reply.json';raw=json.loads((source/(route+'.json')).read_text());numbered=json.loads((source/('numbered-'+route+'.json')).read_text());payload={'route':route,'expected':json.loads((root/'evals/fixtures/guided-selection-cases.json').read_text()),'numberedExpected':json.loads((root/'evals/fixtures/guided-numbered-cases.json').read_text()),'guidance':json.loads((root/'evals/fixtures/behavior-sources/guidance-ai-v0.1.3.json').read_text()),'bootstrap':raw.get('skillManifest') or (root/'evals/fixtures/guided-bootstrap-tested.md').read_text(),'entry':(root/'evals/fixtures/behavior-sources/entry-ai-v0.1.3-zh.md').read_text(),'catalog':(root/'content/zh/prompts/index.md').read_text(),'scenes':(root/'content/zh/scenarios/roleplay-coach/index.md').read_text(),'selectedScene':(root/'content/zh/scenarios/roleplay-coach/project-deep-dive-mock.md').read_text(),'guides':(root/'content/zh/guides/index.md').read_text(),'selectedGuide':(root/'content/zh/guides/choose-feedback-style.md').read_text(),'readingTask':(root/'content/zh/prompts/reading-check.md').read_text(),'turns':turns(raw),'numberedTurns':turns(numbered)};request=policy+json.dumps(payload,ensure_ascii=False);command=['codex','exec','--ignore-user-config','--ignore-rules','--ephemeral','--skip-git-repo-check','--sandbox','read-only','--disable','shell_tool','-m','gpt-6.1-sol','--json','-c','web_search="disabled"','--output-schema',str(schema_path),'--output-last-message',str(reply),'-'];started=datetime.datetime.now(datetime.timezone.utc).isoformat();result=subprocess.run(command,input=request,text=True,cwd=directory,env=env,capture_output=True,timeout=240);events=[json.loads(l)for l in result.stdout.splitlines()if l.startswith('{')];record={'route':route,'sourceProbeSha256':hashlib.sha256((source/(route+'.json')).read_bytes()).hexdigest(),'numberedProbeSha256':hashlib.sha256((source/('numbered-'+route+'.json')).read_bytes()).hexdigest(),'policy':policy,'request':request,'requestSha256':hashlib.sha256(request.encode()).hexdigest(),'command':command,'startedAt':started,'exitCode':result.returncode,'events':events,'output':json.loads(reply.read_text())if reply.exists()else None,'stderr':result.stderr};(directory/'judge.json').write_text(json.dumps(record,ensure_ascii=False,indent=2)+'\n');print(route,json.dumps(record['output'],ensure_ascii=False),flush=True)
with concurrent.futures.ThreadPoolExecutor(max_workers=2)as pool:list(pool.map(judge,['skill-web','mcp']))
print('JUDGMENTS',out,flush=True)
